const item = $input.first().json;

// If Fetch Events failed (401, 403, or network error), the item has an error field
const isFailed = !!item.error;
const statusCode = item.error?.status || item.statusCode || 200;
const errorMessage = item.error?.message || null;

return [{
  json: {
    oauth_status: isFailed ? 'failed' : 'success',
    oauth_error: errorMessage,
    http_status: statusCode,
    response_ok: !isFailed
  }
}];

const item = $input.first().json;

// If Fetch Events failed, return empty array â€” nothing to process
if (item.error) {
  return [];
}

const events = item.items || [];
const results = [];

for (const event of events) {
  // Filter 1: Skip all-day events (no dateTime, only date)
  if (event.start?.date && !event.start?.dateTime) {
    continue;
  }

  // Filter 2: Skip cancelled events
  if (event.status === 'cancelled') {
    continue;
  }

  // Parse start and end times
  const startTime = new Date(event.start.dateTime);
  const endTime = new Date(event.end.dateTime);

  // Skip events with invalid timestamps
  if (isNaN(startTime) || isNaN(endTime)) {
    continue;
  }

  // Compute duration in minutes
  const durationMinutes = Math.round((endTime - startTime) / 60000);

  // Count attendees (excluding the organizer if they're in the list)
  const attendees = event.attendees || [];
  const attendeeCount = attendees.filter(a => !a.organizer).length;

  results.push({
    json: {
      gcal_event_id: event.id,
      event_summary: event.summary || '(no title)',
      event_start: startTime.toISOString(),
      event_end: endTime.toISOString(),
      attendee_count: attendeeCount,
      duration_minutes: durationMinutes,
      event_description: event.description || null,
      event_html_link: event.htmlLink || null,
      organizer_email: event.organizer?.email || null
    }
  });
}

// At the end of Extract Event Fields
return results;

// Filter Already Posted
// Reads events from Extract Event Fields by name (not $input), because
// Query All Posted IDs replaced its input with the query result.

const currentItems = $('Extract Event Fields').all();

// Fetch posted event IDs from the audit table
const postedRows = $('Query All Posted IDs').all().map(r => r.json.gcal_event_id);
const postedSet = new Set(postedRows.filter(id => id != null));

// Filter out events already in the audit table
return currentItems.filter(item => {
  return item.json.gcal_event_id && !postedSet.has(item.json.gcal_event_id);
});

