const item = $input.first().json;
const event = $('Extract Event Fields').first().json;

// Extract the response body regardless of shape
let responseBody = null;

if (typeof item === 'string') {
  responseBody = item;
} else if (item.data && typeof item.data === 'string') {
  responseBody = item.data;
} else if (item.body && typeof item.body === 'string') {
  responseBody = item.body;
} else if (item.ok === true) {
  responseBody = 'ok';
}

const isError = !!item.error;
const isOkResponse = responseBody && responseBody.trim() === 'ok';

let slackMessageTs = null;
let slackError = null;

if (isError) {
  slackError = item.error?.message || JSON.stringify(item.error);
} else if (!isOkResponse) {
  slackError = `Unexpected Slack response: ${String(responseBody).slice(0, 200)}`;
}

return [{
  json: {
    gcal_event_id: event.gcal_event_id,
    event_summary: event.event_summary,
    event_start: event.event_start,
    event_end: event.event_end,
    attendee_count: event.attendee_count,
    duration_minutes: event.duration_minutes,
    slack_post_status: isError ? 'failed' : (isOkResponse ? 'success' : 'failed'),
    slack_message_ts: isOkResponse ? 'ok' : null,
    slack_error: slackError
  }
}];

